function harga(x: string | number | null): string {
  if (x === null) return "belum ada harga";
  if (typeof x === "number") return "Rp" + x.toLocaleString("id-ID");
  return x.trim() === "" ? "kosong" : x.trim().toUpperCase();
}
console.log(harga(25000));
console.log(harga("  gratis "));
console.log(harga(null));
console.log(harga("   "));

