cards.solution:
function rapikan(x: string | number | null | undefined): string {
  if (x === null || x === undefined) return "-";
  if (typeof x === "number") return x.toFixed(2);
  return x.trim().toUpperCase();
}
console.log(rapikan(null));
console.log(rapikan(3.5));
console.log(rapikan("  teh "));
